            java.io.File original=new java.io.File(source.getPath()+suffix),copy=new java.io.File(folder,source.getName()+suffix);
            if(original.exists()&&!copy.exists())java.nio.file.Files.copy(original.toPath(),copy.toPath());
        }
    }
